'use strict';
const places = [
 {name:'Дворцовая площадь',category:'architecture',label:'Архитектура',sub:'Сердце императорского Петербурга',coord:[30.3158,59.9390],description:'Главная площадь города между Зимним дворцом и зданием Главного штаба.',shape:'palace',color:'#d7dfcc'},
 {name:'Исаакиевский собор',category:'architecture',label:'Архитектура',sub:'Купол над городом',coord:[30.3064,59.9343],description:'Монументальный собор у Исаакиевской площади. Рассмотрите окружающие кварталы в объёме.',shape:'dome',color:'#e4dcc7'},
 {name:'Стрелка Васильевского острова',category:'water',label:'У воды',sub:'Там, где Нева разделяется',coord:[30.3066,59.9435],description:'Восточная оконечность Васильевского острова с Ростральными колоннами и видом на Неву.',shape:'columns',color:'#cadcd6'},
 {name:'Петропавловская крепость',category:'parks',label:'Парки и острова',sub:'Начало города на Заячьем острове',coord:[30.3175,59.9500],description:'Историческая крепость на Заячьем острове. Обойдите остров на карте и найдите свой ракурс.',shape:'spire',color:'#dce1c4'},
 {name:'Новая Голландия',category:'parks',label:'Парки и острова',sub:'Остров внутри города',coord:[30.2876,59.9295],description:'Остров, окружённый Мойкой, Крюковым и Адмиралтейским каналами.',shape:'arch',color:'#e4d4c7'},
 {name:'Севкабель Порт',category:'water',label:'У воды',sub:'Открытый горизонт Финского залива',coord:[30.2400,59.9243],description:'Общественное пространство на западном берегу Васильевского острова.',shape:'port',color:'#cdd9df'}
];
const $ = s => document.querySelector(s);
const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
function artwork(p){
 const windowRow=Array.from({length:10},(_,i)=>`<path d="M${65+i*21} 118v13m0 8v13" stroke="#6f8064" stroke-width="6"/>`).join('');
 const shapes={palace:`<path d="M48 103h245v57H48z" fill="#a4b595"/><path d="M40 101h260v8H40zM48 153h245v7H48z" fill="#728463"/>${windowRow}<path d="M166 70h7v89h-7z" fill="#7a8068"/><path d="M160 68h19v7h-19z" fill="#65735d"/><path d="M166 57h6v13h-6z" fill="#65735d"/>`,dome:`<path d="M95 116h150v45H95z" fill="#b2aa91"/><path d="M85 115l85-28 85 28z" fill="#8b8d73"/><path d="M137 90V74a33 30 0 0 1 66 0v16" fill="#a39b6a"/><path d="M133 88h74v8h-74zM165 37h10v12h-10z" fill="#7d805f"/><path d="M170 27v13m-5-8h10" stroke="#6d755e" stroke-width="3"/><path d="M110 122v35m24-35v35m24-35v35m24-35v35m24-35v35m24-35v35" stroke="#e2dcc5" stroke-width="9"/>`,columns:`<path d="M0 155Q110 141 340 157V220H0" fill="#94b7ad"/><path d="M65 150h210l-35-15H105z" fill="#e5e5cf"/><path d="M110 63h14v78h-14zM218 63h14v78h-14z" fill="#a47961"/><path d="M105 62h24m84 0h24M103 83l28 7m-28 13 28 7m79-27 28 7m-28 13 28 7" stroke="#886d55" stroke-width="5"/><path d="M143 116h55v24h-55z" fill="#b4c2ab"/><path d="M138 115l32-18 33 18" fill="#83977c"/>`,spire:`<path d="M35 150l40-18h190l40 18-58 20H95z" fill="#a8b389"/><path d="M85 129h170v24H85z" fill="#c8c6a0"/><path d="M159 94h24v50h-24z" fill="#a9a166"/><path d="M157 92l14-23 14 23zM169 69l2-49 3 49z" fill="#9b9150"/><path d="M110 122h30v22h-30zM201 122h30v22h-30z" fill="#b4b28c"/><path d="M0 175q170-18 340 0v45H0" fill="#a4bdb0"/>`,arch:`<path d="M60 75h220v91H60z" fill="#b68d73"/><path d="M143 166v-48a28 28 0 0 1 56 0v48" fill="#e4d4c7"/><path d="M52 73h236v9H52zM57 156h86v10H57zM199 156h85v10h-85z" fill="#8b765e"/><path d="M82 93v17m26-17v17m122-17v17m26-17v17" stroke="#725f4f" stroke-width="8"/><path d="M0 180q150-20 340 0v40H0" fill="#adbdb4"/>`,port:`<path d="M0 153h340v67H0z" fill="#9cb6be"/><path d="M35 113h160v42H35zM195 155V96h29v59" fill="#b2ad99"/><path d="M31 112l82-25 86 25z" fill="#7e8e89"/><path d="M59 124h12v17H59zM88 124h12v17H88zM117 124h12v17h-12zM146 124h12v17h-12z" fill="#687d7b"/><path d="M254 139V66h4v73m-2-72 48 19m-48-19-24 25m69-6v30" stroke="#677f7b" stroke-width="3" fill="none"/>`};
 return `<svg viewBox="0 0 340 220" role="img" aria-label="Иллюстрация: ${p.name}" xmlns="http://www.w3.org/2000/svg"><rect width="340" height="220" fill="${p.color}"/><circle cx="275" cy="49" r="23" fill="#f9f7e3" opacity=".6"/><path d="M0 164h340" stroke="#a6b398"/>${shapes[p.shape]}</svg>`;
}
function renderPlaces(filter='all'){ $('#place-grid').innerHTML=places.map((p,i)=>filter==='all'||p.category===filter?`<button class="place-card" data-place="${i}" aria-label="Показать на карте: ${p.name}"><div class="card-art">${artwork(p)}<span class="number">0${i+1} / SPB</span><span class="tag">${p.label}</span></div><div class="card-title">${p.name}<span>↗</span></div><p>${p.sub}</p></button>`:'').join(''); }
renderPlaces();
let map, ready=false, is3d=true, night=false, lastFocus;
const status=$('#map-status');
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function expand(){lastFocus=document.activeElement;$('.map-shell').classList.add('expanded');document.body.classList.add('map-open');$('#close-map').hidden=false;map?.resize();$('#search').focus();}
function collapse(){$('.map-shell').classList.remove('expanded');document.body.classList.remove('map-open');$('#close-map').hidden=true;map?.resize();lastFocus?.focus();}
function selectPlace(i){if(!map||!ready){toast('Карта ещё загружается. Попробуйте через несколько секунд.');return;}const p=places[i];expand();map.flyTo({center:p.coord,zoom:16,pitch:is3d?58:0,bearing:-20,duration:reduced?0:1600});new maplibregl.Popup({offset:20}).setLngLat(p.coord).setHTML(`<h3>${p.name}</h3><p>${p.description}</p>`).addTo(map);$('#results').hidden=true;$('#search').value='';}
document.addEventListener('click',e=>{const p=e.target.closest('[data-place]');if(p)selectPlace(Number(p.dataset.place));const f=e.target.closest('[data-filter]');if(f){document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===f);b.setAttribute('aria-pressed',b===f)});renderPlaces(f.dataset.filter);}if(!e.target.closest('.search-box'))$('#results').hidden=true;});
document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',expand));$('#close-map').onclick=collapse;
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#results').hidden)$('#results').hidden=true;else collapse();}if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();expand();}if(e.key==='Tab'&&document.body.classList.contains('map-open')){const focusable=[...$('.map-shell').querySelectorAll('button:not([hidden]),input,a[href],canvas[tabindex]')].filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function search(){const q=$('#search').value.trim().toLocaleLowerCase('ru');const matches=places.map((p,i)=>({p,i})).filter(({p})=>(p.name+' '+p.sub+' '+p.label).toLocaleLowerCase('ru').includes(q));$('#results').innerHTML=matches.length?matches.map(({p,i})=>`<button data-place="${i}">${p.name} ↗</button>`).join(''):'<p>В подборке нет такого места. Попробуйте «Исаакиевский» или «Новая Голландия».</p>';$('#results').hidden=false;}
$('#search').addEventListener('input',search);$('#search').addEventListener('focus',search);$('#search').addEventListener('keydown',e=>{if(e.key==='ArrowDown'){$('#results button')?.focus();e.preventDefault();}if(e.key==='Enter')$('#results button')?.click();});
function setTheme(value){night=value;$('#day').classList.toggle('active',!night);$('#night').classList.toggle('active',night);$('#day').setAttribute('aria-pressed',!night);$('#night').setAttribute('aria-pressed',night);if(map){ready=false;status.textContent='Меняем освещение…';status.hidden=false;map.setStyle('https://tiles.openfreemap.org/styles/'+(night?'dark':'positron'),{diff:false});}}
$('#day').onclick=()=>setTheme(false);$('#night').onclick=()=>setTheme(true);
$('#zoom-in').onclick=()=>map?.zoomIn({duration:reduced?0:300});$('#zoom-out').onclick=()=>map?.zoomOut({duration:reduced?0:300});$('#reset').onclick=()=>map?.flyTo({center:[30.3141,59.939],zoom:15.4,bearing:-25,pitch:is3d?58:0,duration:reduced?0:1000});
$('#dimension').onclick=()=>{is3d=!is3d;$('#dimension').textContent=is3d?'3D':'2D';$('#dimension').setAttribute('aria-pressed',is3d);if(map?.getLayer('spb-buildings'))map.setLayoutProperty('spb-buildings','visibility',is3d?'visible':'none');map?.easeTo({pitch:is3d?58:0,duration:reduced?0:650});};
$('#share').onclick=async()=>{if(!map)return;const c=map.getCenter();const url=new URL(location.href);url.hash=`view=${c.lng.toFixed(5)},${c.lat.toFixed(5)},${map.getZoom().toFixed(2)},${map.getBearing().toFixed(1)},${map.getPitch().toFixed(1)},${night?1:0}`;try{await navigator.clipboard.writeText(url.href);toast('Ссылка с вашим ракурсом скопирована');}catch{history.replaceState(null,'',url);toast('Ракурс сохранён в адресе страницы — скопируйте ссылку из браузера.');}};
try{
 if(typeof maplibregl==='undefined')throw Error('Библиотека карты недоступна');
 const view=location.hash.startsWith('#view=')?location.hash.slice(6).split(',').map(Number):[];
 const valid=view.length===6&&view.every(Number.isFinite)&&view[0]>=29.4&&view[0]<=30.8&&view[1]>=59.6&&view[1]<=60.15;
 night=valid&&view[5]===1;is3d=!valid||view[4]>0;
 $('#day').classList.toggle('active',!night);$('#night').classList.toggle('active',night);$('#day').setAttribute('aria-pressed',!night);$('#night').setAttribute('aria-pressed',night);$('#dimension').textContent=is3d?'3D':'2D';$('#dimension').setAttribute('aria-pressed',is3d);
 map=new maplibregl.Map({container:'map',style:'https://tiles.openfreemap.org/styles/'+(night?'dark':'positron'),center:valid?view.slice(0,2):[30.3141,59.939],zoom:valid?Math.max(10,Math.min(19,view[2])):15.4,pitch:valid?Math.max(0,Math.min(70,view[4])):58,bearing:valid?view[3]:-25,maxBounds:[[29.4,59.6],[30.8,60.15]],minZoom:10,maxZoom:19,maxPitch:70,attributionControl:true,canvasContextAttributes:{antialias:true}});
 map.addControl(new maplibregl.ScaleControl({maxWidth:90,unit:'metric'}),'bottom-left');
 map.on('style.load',()=>{const layers=map.getStyle().layers;const source=layers.find(l=>l['source-layer']==='building')?.source||'openmaptiles';const before=layers.find(l=>l.type==='symbol')?.id;map.addLayer({id:'spb-buildings',source,'source-layer':'building',type:'fill-extrusion',minzoom:13,layout:{visibility:is3d?'visible':'none'},paint:{'fill-extrusion-color':night?'#708377':'#c6cfb5','fill-extrusion-height':['coalesce',['get','render_height'],['get','height'],8],'fill-extrusion-base':['coalesce',['get','render_min_height'],['get','min_height'],0],'fill-extrusion-opacity':.92}},before);ready=true;status.hidden=true;});
 map.on('load',()=>{places.forEach((p,i)=>{const el=document.createElement('button');el.className='place-marker';el.textContent=String(i+1).padStart(2,'0');el.setAttribute('aria-label',p.name);el.onclick=e=>{e.stopPropagation();selectPlace(i)};new maplibregl.Marker({element:el}).setLngLat(p.coord).addTo(map);});if(valid)expand();});
 const failTimer=setTimeout(()=>{if(!ready){status.hidden=false;status.textContent='Карта загружается дольше обычного. Проверьте подключение к интернету и обновите страницу.';}},18000);
 map.once('idle',()=>clearTimeout(failTimer));map.on('error',e=>{if(!ready)console.warn('Map data unavailable:',e.error?.message);});
}catch(e){status.hidden=false;status.textContent='Не удалось открыть 3D-карту. Нужны интернет и браузер с WebGL. Попробуйте обновить страницу.';console.warn(e.message);}

